<?php declare(strict_types=1);require dirname(__DIR__).'/_bootstrap.php';require_get();$user=api_user();$hunt=(int)input('hunt_id');$s=db()->prepare("SELECT v.id,v.location_id,v.title,v.video_url,v.sort_order FROM hunt_videos v JOIN hunt_user_activations a ON a.hunt_id=v.hunt_id AND a.user_id=? AND a.status IN ('ACTIVE','COMPLETED') WHERE v.hunt_id=? AND v.status='ACTIVE' ORDER BY v.sort_order,v.id");$s->execute([$user['id'],$hunt]);json_response(true,'Hunt videos',['items'=>$s->fetchAll()]);
